package mod.cdv.tnpc.tactical;
import java.util.*;
public final class NpcMedicine {
 static final String AID="dev.zomboid.firstaid.NpcAid7";static final Map<Object,PlayerTreatment> TREATMENTS=new WeakHashMap<>();
 static Object c(Object o,String n,Object...a){return Social.c(o,n,a);}static boolean medical(Object s)throws Exception{String id=CalmLoot.id(s);return id.equals("firstaid:bandage")||id.equals("firstaid:plaster")||id.contains("military_bandage");}
 static boolean defib(Object s){return Social.yes(c(Social.t("ichttt.mods.firstaid.common.EventHandler"),"isDefibrillator",s));}
 static Object aid(String method,Object...a){return c(Social.t(AID),method,a);}static boolean down(Object p){return Social.yes(aid("down",p));}
 static Object supply(Object n,boolean defib)throws Exception{for(Object s:CalmLoot.bag(n))if(defib?defib(s):medical(s))return s;return null;}
 static boolean consume(Object n,boolean defib)throws Exception{List<Object> list=CalmLoot.bag(n);for(Object s:list)if(defib?defib(s):medical(s)){if(defib){int damage=((Number)c(s,"getDamageValue")).intValue()+1;if(damage>=5)c(s,"shrink",1);else{c(s,"set",SocialR.get(Social.t("net.minecraft.core.component.DataComponents"),"MAX_DAMAGE"),5);c(s,"setDamageValue",damage);}}else c(s,"shrink",1);list.removeIf(x->Social.yes(c(x,"isEmpty")));CalmLoot.saveBag(n,list);return true;}return false;}
 static void init(Object n){if(Social.i(Social.tag(n),"np15_parts")==0)c(Social.t("dev.zomboid.npcprobe.Parts"),"init",n,null);}
 public static void damage(Object n,Object source,float amount){init(n);int zone=1;Object direct=c(source,"getDirectEntity");if(direct!=null){double height=Social.num(c(n,"getBbHeight"));double y=(Social.num(c(direct,"getY"))-Social.num(c(n,"getY")))/Math.max(.1,height);double yaw=Math.toRadians(Social.num(c(n,"getYRot")));double side=(Social.num(c(direct,"getX"))-Social.num(c(n,"getX")))*Math.cos(yaw)+(Social.num(c(direct,"getZ"))-Social.num(c(n,"getZ")))*Math.sin(yaw);zone=(Integer)c(Social.t("dev.zomboid.npcprobe.Parts"),"zone",y,side);}String[] keys={"head","body","leftArm","rightArm","leftLeg","rightLeg","leftFoot","rightFoot"};String key="np15_hp_"+keys[zone];c(Social.tag(n),"putDouble",key,Math.max(0,Social.num(c(Social.tag(n),"getDouble",key))-amount));}
 static boolean healNpc(Object n,float amount){if(Downed20.down(n))return false;init(n);String[] keys={"head","body","leftArm","rightArm","leftLeg","rightLeg","leftFoot","rightFoot"};boolean wounded=Social.num(c(n,"getHealth"))<Social.num(c(n,"getMaxHealth"));for(String key:keys){double hp=Social.num(c(Social.tag(n),"getDouble","np15_hp_"+key)),max=Social.num(c(Social.tag(n),"getDouble","np15_max_"+key));if(hp<max){c(Social.tag(n),"putDouble","np15_hp_"+key,Math.min(max,hp+amount));wounded=true;break;}}if(wounded)c(n,"heal",amount);return wounded;}
 public static boolean playerTreat(Object n,Object p)throws Exception{Object held=c(p,"getMainHandItem");if(!medical(held))held=c(p,"getOffhandItem");if(!medical(held))return false;if(TREATMENTS.containsKey(n))return true;if(Social.distance(n,p)>9||!Social.visible(n,p))return true;TREATMENTS.put(n,new PlayerTreatment(p,held,Social.time(n),-1));Social.say(p,"soc.treat.start");return true;}
 static boolean playerTreat(Object n,Object p,int part)throws Exception{if(TREATMENTS.containsKey(n)||!NpcClinic20.injured(n,part))return false;boolean result=playerTreat(n,p);PlayerTreatment t=TREATMENTS.get(n);if(t!=null)TREATMENTS.put(n,new PlayerTreatment(p,t.stack,t.start,part));return result;}
 static boolean healPart(Object n,int part,float amount){if(part<0)return healNpc(n,amount);if(Downed20.down(n)||!NpcClinic20.injured(n,part))return false;String key=NpcClinic20.KEYS[part];double old=Social.num(c(Social.tag(n),"getDouble","np15_hp_"+key)),max=Social.num(c(Social.tag(n),"getDouble","np15_max_"+key));double delta=Math.min(amount,max-old);c(Social.tag(n),"putDouble","np15_hp_"+key,old+delta);c(n,"heal",(float)delta);return true;}
 static void treatment(Object n,long now)throws Exception{PlayerTreatment a=TREATMENTS.get(n);if(a==null)return;Social.mem(n).occupied=true;Social.mem(n).medicalUntil=now+25;if(!Social.alive(a.player)||Social.world(n)!=Social.world(a.player)||(c(a.player,"getMainHandItem")!=a.stack&&c(a.player,"getOffhandItem")!=a.stack)||Social.distance(n,a.player)>9||!Social.visible(n,a.player)||CalmLoot.empty(a.stack)){TREATMENTS.remove(n);if(a.part>=0)NpcClinic20.send(n,a.player);return;}if(now-a.start<60){if(a.part>=0&&now%10==0)NpcClinic20.send(n,a.player);return;}TREATMENTS.remove(n);if(healPart(n,a.part,5)){c(a.stack,"shrink",1);c(c(a.player,"getInventory"),"setChanged");Social.trust(n,a.player,12);Social.ledger("change",Social.server(n),Social.identity(a.player),2);Social.say(a.player,"soc.treat.done");Expression20.react(n,a.player,"treated");}else Social.say(a.player,"soc.treat.healthy");if(a.part>=0)NpcClinic20.send(n,a.player);}
 public static void tick(Object n,Social.Memory m,long now)throws Exception{treatment(n,now);if(TREATMENTS.containsKey(n))return;if(m.patient!=null){Object p=m.patient;if(!Social.alive(p)||Social.distance(n,p)>9||!Social.visible(n,p)||((Number)SocialR.get(n,"hurtTime")).intValue()>0){m.patient=null;m.medicalUntil=0;return;}c(c(n,"getNavigation"),"stop");CalmBrain.crouch(n,true);if(!m.patientNpc&&now%20<5)Social.say(p,"soc.rescue.progress",Math.min(100,(now-m.medicalStart)*100/Math.max(1,m.medicalUntil-m.medicalStart)));
   if(now>=m.medicalUntil){if(m.patientNpc){if(supply(n,false)!=null&&healNpc(p,5))consume(n,false);m.patient=null;m.patientNpc=false;m.medicalUntil=0;m.nextMedicine=now+100;CalmBrain.crouch(n,false);return;}boolean rescue=down(p);boolean hasDefib=supply(n,true)!=null;if(rescue){if(Social.yes(aid("revive",p,hasDefib))&&hasDefib)consume(n,true);}else if(supply(n,false)!=null&&Social.yes(aid("heal",p,5f)))consume(n,false);m.patient=null;m.medicalUntil=0;m.nextMedicine=now+100;CalmBrain.crouch(n,false);}return;}
  if(now<m.nextMedicine)return;m.nextMedicine=now+20;
  for(Object p:Social.nearby(n,Social.PLAYER,16)){if(!Social.alive(p)||!Social.visible(n,p)||Social.enemy(n,p)||!SocialRules.aid(Social.kind(n),Social.member(n,p),Social.trust(n,p),Social.known(n,p)))continue;boolean rescue=down(p);if(!rescue&&(supply(n,false)==null||Social.num(aid("missing",p))<2))continue;
   if(Social.distance(n,p)>6.25){Social.hold(n,m);Social.move(n,p,1.05);m.medicalUntil=now+25;return;}Social.hold(n,m);m.patient=p;m.patientNpc=false;m.medicalStart=now;m.medicalUntil=now+(rescue?(supply(n,true)!=null?60:160):60);Social.say(p,rescue?"soc.rescue.start":"soc.heal.start");return;}
  if(supply(n,false)!=null)for(Object other:Social.nearby(n,Social.NPC,8)){if(other==n||!Social.alive(other)||!Social.visible(n,other)||Social.num(c(other,"getHealth"))>=Social.num(c(other,"getMaxHealth"))*.85||!(Boolean.TRUE.equals(Social.allied(n,other))||Social.kind(n)!=0&&Social.kind(other)!=0))continue;if(Social.distance(n,other)>6.25){Social.hold(n,m);Social.move(n,other,.95);m.medicalUntil=now+25;return;}Social.hold(n,m);m.patient=other;m.patientNpc=true;m.medicalStart=now;m.medicalUntil=now+60;return;}
  if(Social.num(c(n,"getHealth"))<Social.num(c(n,"getMaxHealth"))*.8&&supply(n,false)!=null&&m.threats<3){if(m.selfAidStart<0)m.selfAidStart=now;Social.hold(n,m);m.medicalUntil=now+25;CalmBrain.crouch(n,true);if(now-m.selfAidStart>=60){if(healNpc(n,5))consume(n,false);m.selfAidStart=-1;m.nextMedicine=now+200;m.medicalUntil=0;CalmBrain.crouch(n,false);}}
 }
 record PlayerTreatment(Object player,Object stack,long start,int part){}
}
